addField:
function addField(school, x, y, radius) {
  const block=school === "water" ? cardBlock("water-skill","onWaterHit").actions[0] : school === "thunder" ? cardBlock("fusion-dash","onDashTrail").actions[0] : null;
  if(radius===undefined) radius=block?block.radius:BUILD_TUNING.fieldRadius;
  if (state.fields.length >= (block?block.limit:BUILD_TUNING.fieldLimit)) state.fieldPool.push(state.fields.shift());
  state.fields.push(takeFromPool(state.fieldPool, { school, x, y, radius: radius * (1 + Math.max(0, effectLevel(school === "water" ? "water-skill" : "wind-dash") - 1) * (block?block.radiusGrowth:BUILD_TUNING.fieldRadiusGrowth)), life: block?block.seconds:BUILD_TUNING.fieldSeconds, timer: 0 }));
}

updateFields:
function updateFields(dt) {
  for (let i = state.fields.length - 1; i >= 0; i--) {
    const field = state.fields[i]; field.life -= dt; field.timer -= dt;
    if (field.life <= 0) { state.fieldPool.push(state.fields.splice(i, 1)[0]); continue; }
    if (field.timer > 0) continue;
    const block=field.school === "water" ? cardBlock("water-skill","onWaterHit").actions[0] : field.school === "thunder" ? cardBlock("fusion-dash","onDashTrail").actions[0] : null;
    field.timer += block?block.interval:BUILD_TUNING.fieldInterval;
    for (const target of combatTargets()) {
      if (Math.hypot(deltaX(target.x, field.x), deltaY(target.y, field.y)) > field.radius + target.r) continue;
      const level = field.school === "water" ? Math.max(effectLevel("water-skill"), effectLevel("water-dash"), effectLevel("fusion-storm")) : field.school === "wind" ? effectLevel("wind-dash") : effectLevel("fusion-dash");
      if (field.school === 'water') hitBuildTarget(target,cardBlock('water-skill','onFieldTick',{level}).actions[0].amount);
      else hitBuildTarget(target, block?block.damage:BUILD_TUNING.fieldDamage * Math.max(1, level));
      if (field.school === "water") {
        const tick=cardBlock('water-skill','onFieldTick',{level});
        applyCardTargetActions({actions:tick.actions.slice(1)},target);
        if (effectLevel("fusion-puddle")) { lightning(field.x, field.y, target.x, target.y); applyCardTargetActions(cardBlock('fusion-puddle','onFieldTick'),target); burst(target.x, target.y, BUILD_TUNING.thunder.color, 3); }
      }
      if (field.school === "wind") shiftTarget(target, field.x, field.y, BUILD_TUNING.pushDistance * Math.max(1, level));
      if (field.school === "thunder") schoolEffect("thunder", target, target.x, target.y, block.damage);
      if (state.mode !== "playing") return;
    }
  }
}

leaveDashTrail:
function leaveDashTrail(x, y, distance, fromX = x, fromY = y) {
  // 沿走過的路每隔一小段留痕跡，速度變快時也不會留下大空洞。
  const spacing = Math.max(1, effectLevel("fusion-dash") ? cardBlock("fusion-dash","onDashTrail").actions[0].spacing : cardBlock("water-dash","onDashTrail").actions[0].spacing);
  let next = Math.max(0, spacing - state.trailDistance);
  while (next <= distance) {
    const fraction = distance > 0 ? next / distance : 0;
    for (const school of ["water", "wind", "thunder"]) if ((school === "water" && (effectLevel("water-dash") || effectLevel("fusion-storm"))) || (school === "wind" && (effectLevel("wind-dash") || effectLevel("fusion-storm"))) || (school === "thunder" && effectLevel("fusion-dash"))) addField(school, fromX + (deltaX(x, fromX)) * fraction, fromY + (deltaY(y, fromY)) * fraction);
    for (const card of UPGRADES) if (upgradeLevel(card.id)) for (const effect of card.effects) {
      if (!effect.feature && effect.type === "dash-trail" && effect.trigger === "dash") executeMakerEffect(effect, fromX + (deltaX(x, fromX))*fraction, fromY + (deltaY(y, fromY))*fraction, upgradeLevel(card.id));
    }
    next += spacing;
  }
  state.trailDistance = (state.trailDistance + distance) % spacing;
}

updateOneUltimate:
function updateOneUltimate(dt, selectedSchool) {
  if (state.ultimateVisual) { state.ultimateVisual.life -= dt; if (state.ultimateVisual.life <= 0) state.ultimateVisual = null; }
  const ultimateSchool = selectedSchool;
  const card = ultimateSchool ? { school: ultimateSchool, id: ultimateSchool + "-ultimate" } : null;
  if (!card) return;
  state.ultimateTimer = countdown(state.ultimateTimer || 0, dt);
  if (state.ultimateTimer > 0) {
    if (card.school === "wind" && state.ultimateVisual) {
      state.ultimateVisual.x = state.player.x + Math.cos(state.elapsed * BUILD_TUNING.tornadoSpeed) * BUILD_TUNING.tornadoRadius;
      state.ultimateVisual.y = state.player.y + Math.sin(state.elapsed * BUILD_TUNING.tornadoSpeed) * BUILD_TUNING.tornadoRadius;
    }
    return;
  }
  const ultimateBlock=card.school !== "wind" ? cardBlock(card.id,"onUltimate") : null;
  const level = effectLevel(card.id), damage = ultimateBlock ? ultimateBlock.actions[0].amount : BUILD_TUNING.ultimateDamage * (1 + (level - 1) * BUILD_TUNING.ultimateGrowth);
  let targets = combatTargets();
  const x = state.player.x + Math.cos(state.elapsed * BUILD_TUNING.tornadoSpeed) * BUILD_TUNING.tornadoRadius;
  const y = state.player.y + Math.sin(state.elapsed * BUILD_TUNING.tornadoSpeed) * BUILD_TUNING.tornadoRadius;
  if (card.school === "thunder") targets = SurvivorEffectBlocks.select(ultimateBlock,targets,targets.length?Math.random():0);
  if (card.school === "wind") targets = targets.filter(target => Math.hypot(deltaX(target.x, x), deltaY(target.y, y)) < BUILD_TUNING.fieldRadius + target.r);
  state.ultimateVisual = { worldWidth: state.worldWidth, worldHeight: state.worldHeight, school: card.school, x: card.school === "thunder" && targets.length ? targets[0].x : x, y: card.school === "thunder" && targets.length ? targets[0].y : y, life: card.school === "water" ? 1.2 : .5 };
  state.ultimateTimer = card.school === "wind" ? BUILD_TUNING.tornadoTick : ultimateBlock.interval;
  for (const target of targets) { if (card.school === "thunder") lightning(target.x, target.y - 90, target.x, target.y); hitBuildTarget(target, damage); burst(target.x, target.y, BUILD_TUNING[card.school].color, 5); if (state.mode !== "playing") return; }
}

activateSkill:
function activateSkill() {
  if (state.mode !== "playing" || state.skillCooldown > 0 || state.bomb) return;
  state.bomb = { x: state.player.x, y: state.player.y, timer: gameSettings.bombDelay,
    delay: gameSettings.bombDelay, radius: gameSettings.bombRadius, damage: gameSettings.bombDamage, knockback: gameSettings.bombKnockback, schools: ["water", "wind", "thunder"].filter((school) => effectLevel(`${school}-skill`) || school === "wind" && effectLevel("wind-dash")) };
  state.skillCooldown = gameSettings.bombCooldown;
  triggerMakerEffects("skill", state.player.x, state.player.y);
  playSound("water");
 updateActionControls();
}

schoolDashEnded:
function schoolDashEnded() {
  const c = state.schoolCombat, r = GAME_DATA.schoolRules;
  if (!c) return;
  if (effectLevel('water-bubble')) c.bubble = cardBlock('water-bubble','onDashEnd').actions[0].active;
  if (effectLevel('wind-refund')) {
    // 半格是回充進度，不能用半格再發動一次完整衝刺。
    state.dashCooldown = Math.max(0, state.dashCooldown - gameSettings.dashCooldown * r.refundCharge);
    if (state.dashCooldown === 0 && state.dashCharges < maxDashCharges()) { state.dashCharges++; state.dashCooldown = state.dashCharges < maxDashCharges() ? gameSettings.dashCooldown : 0; }
  }
}

schoolShotHit:
function schoolShotHit(shot, target) {
  const r = GAME_DATA.schoolRules;
  if ((shot.schools || []).includes('water') || effectLevel('water-skill')) applyCardTargetActions(cardBlock('water-skill','onShotHit'),target);
  if (!shot.melee) waveNeutralHit(target,shot.vx,shot.vy);
  if (shot.push) shiftTarget(target, shot.x - shot.vx, shot.y - shot.vy, shot.push);
  if (shot.charged) { lightning(state.player.x,state.player.y,target.x,target.y); schoolEffect('thunder',target,target.x,target.y,shot.damage,shot.hitList); }
  if (!shot.melee && effectLevel('wind-blade') && shot.pierce > 0 && !shot.blade) {
    const other = combatTargets().find(e => !shot.hitList.includes(e) && Math.hypot(deltaX(e.x,target.x),deltaY(e.y,target.y)) <= r.windBladeRange);
    skillVisual('gust',target.x,target.y,{x2:target.x+shot.vx*.15,y2:target.y+shot.vy*.15,color:BUILD_TUNING.wind.color});
    if (other && state.projectiles.length < PROJECTILE_LIMIT) {
      const a = Math.atan2(deltaY(other.y,target.y),deltaX(other.x,target.x));
      state.projectiles.push(takeFromPool(state.projectilePool,{x:target.x,y:target.y,vx:Math.cos(a)*PROJECTILE_SPEED,vy:Math.sin(a)*PROJECTILE_SPEED,r:5,damage:shot.damage*r.windBladeDamage,rangeLeft:r.windBladeRange,hitList:[target],alive:true,blade:true,pierce:0,schools:[],colors:['wind'],transformed:false,push:0,charged:false,maker:true}));
    }
  }
}

updateSchoolCombat:
function updateSchoolCombat(dt) {
  const c = state.schoolCombat, r = GAME_DATA.schoolRules;
  if (!c) return;
  c.still = state.moveRate > .01 ? 0 : c.still + dt;
  for (const target of state.enemies.concat(state.boss ? [state.boss] : [])) target.wetTimer = countdown(target.wetTimer || 0,dt);
  const pulse = (id, seconds, action) => {
    if (!effectLevel(id)) return;
    c.timers[id] = (c.timers[id] === undefined ? seconds : c.timers[id]) - dt;
    if (c.timers[id] > 0) return;
    c.timers[id] += seconds; action();
  };
  const push = (radius, distance, color) => {
    skillVisual('discharge',state.player.x,state.player.y,{radius,color,life:.4});
    for (const target of combatTargets()) if (Math.hypot(deltaX(target.x,state.player.x),deltaY(target.y,state.player.y)) <= radius) shiftTarget(target,state.player.x,state.player.y,distance);
  };
  const fountain=cardBlock('water-fountain','onPulse');
  pulse('water-fountain',fountain.interval,() => {
    push(fountain.conditions[0].radius,fountain.actions[0].distance,BUILD_TUNING.water.color);
    for (const t of combatTargets()) if (cardBlockMatches(fountain.conditions[0],t,state.player.x,state.player.y)) applyCardTargetActions({actions:fountain.actions.slice(1)},t);
  });
  pulse('wind-gust',r.gustSeconds,() => push(r.gustRadius,r.gustPush,BUILD_TUNING.wind.color));
  const rain=cardBlock('water-rain','onPulse');
  pulse('water-rain',rain.interval,() => {
    c.rain = rain.actions[0].duration;
    // 保留全場緩速與濕潤；不造成畫面外傷害。
    for (const target of state.enemies.concat(state.boss ? [state.boss] : [])) applyCardTargetActions({actions:rain.actions.slice(1)},target);
    skillVisual('splash',state.player.x,state.player.y,{radius:rain.actions[0].cueRadius,color:BUILD_TUNING.water.color,life:.8});
  });
  c.rain = countdown(c.rain || 0,dt);
  if (c.rain > 0) for (const t of state.enemies.concat(state.boss ? [state.boss] : [])) {
    const tick=cardBlock('water-rain','onRainTick',{dt});
    t.slowTimer=Math.max(t.slowTimer || 0,tick.actions[0].duration); t.makerSlow=tick.actions[0].multiplier;
    applyCardTargetActions({actions:tick.actions.slice(1)},t);
  }
  const summon=cardBlock('thunder-rod','onSummonTimer'), rodBlock=summon.actions[0];
  pulse('thunder-rod',summon.interval,() => { if (c.rods.length < rodBlock.limit) c.rods.push({x:state.player.x,y:state.player.y,life:rodBlock.seconds,timer:0}); });
  for (const rod of c.rods) {
    rod.life -= dt; rod.timer -= dt;
    if (rod.timer <= 0) {
      rod.timer += rodBlock.interval;
      skillVisual('sparkle',rod.x,rod.y,{radius:20,color:BUILD_TUNING.thunder.color,life:.5});
      for (const target of combatTargets()) if (Math.hypot(deltaX(target.x,rod.x),deltaY(target.y,rod.y)) <= rodBlock.radius) { lightning(rod.x,rod.y,target.x,target.y); hitBuildTarget(target,rodBlock.damage); if(state.mode!=='playing') return; }
    }
  }
  c.rods = c.rods.filter(rod => rod.life > 0);
  if (schoolWindWall()) for (const target of combatTargets()) if (Math.hypot(deltaX(target.x,state.player.x),deltaY(target.y,state.player.y)) < r.eyeRadius + target.r) shiftTarget(target,state.player.x,state.player.y,r.eyePush*dt);
  applyEffectBlockTimer(dt);

}

swingAtNearest:
function swingAtNearest(dash = false, command = null) {
  const target = closestEnemy(), weapon = activeWeapon();
  if (!target && !command) return;
  const c = state.schoolCombat, r = GAME_DATA.schoolRules;
  const sequence=SurvivorEffectBlocks.attack(state.weaponAttack,weapon,state.swingCount);
  const number = sequence.event.number;
  const properties = SurvivorSchools.shot(c ? c.shots + 1 : number,c ? c.kills : 0,c ? c.chargedUsed : 0,{drop:effectLevel('water-drop'),charge:effectLevel('thunder-charge')},r);
  const boosted = state.dashAttack > 0 && state.dashTimer <= 0;
  const look = buildAppearance();
  const event = SurvivorWeapons.swing(weapon,number,command ? command.angle : SurvivorWeapons.aim(weapon,deltaX(target.x,state.player.x),deltaY(target.y,state.player.y),state.faceX,state.faceY),{
    extraArc:effectLevel('multi-water') * UPGRADE_TUNING.extraShotAngle,
    size:properties.size * (transformed('water') ? 1+r.waterFormSize : 1) * (1+effectLevel('big-water')*UPGRADE_TUNING.waterSizePerLevel) * (1+effectLevel('wind-attack')*BUILD_TUNING.windSpeed) * (1+effectLevel('piercing-water')*.1) * (boosted ? UPGRADE_TUNING.dashAttackSize : 1),
    damage:effectiveDamage()*properties.damage*(boosted ? UPGRADE_TUNING.dashAttackDamage : 1),push:properties.push
  },{...sequence.event,dash});
  const targets = combatTargets();
  const hits = targets.filter(t=>SurvivorWeapons.intersects(deltaX(t.x,state.player.x),deltaY(t.y,state.player.y),t.r,event));
  // 目標太遠不空揮，也不消耗蓄電、第四下或衝刺強化。
  if (!hits.length && !command) return;
  state.swingCount++;
  state.weaponAttack=sequence.state; state.lastWeaponAttack=sequence.event; state.attackRecovery=event.recovery;
  triggerMakerEffects('combo',state.player.x,state.player.y,number);
  if(state.mode!=='playing') return;
  if (c) { c.shots++; if (properties.charged) c.chargedUsed = Math.floor(c.kills/r.chargeKills); }
  if (boosted) state.dashAttack = 0;
  const visual = {...event,colors:look.colors.slice(),boosted,life:.24};
  skillVisual('hammer-swing',state.player.x,state.player.y,visual); playSound('shoot');
  // 後射對應後方小扇形；同一揮擊每個目標最多結算一次。
  if (effectLevel('item-rear') && !event.spin && !(command && event.charged)) {
    const rear={...event,angle:event.angle+Math.PI};
    skillVisual('hammer-swing',state.player.x,state.player.y,{...rear,colors:look.colors.slice(),boosted,life:.24});
    for(const t of targets) if(!hits.includes(t) && SurvivorWeapons.intersects(deltaX(t.x,state.player.x),deltaY(t.y,state.player.y),t.r,rear)) hits.push(t);
  }
  for (const t of hits) {
    if (t !== state.boss && !t.alive) continue;
    const shot={x:t.x,y:t.y,vx:deltaX(t.x,state.player.x),vy:deltaY(t.y,state.player.y),damage:event.damage,push:0,charged:properties.charged,schools:effectLevel('water-attack')?['water']:[],hitList:hits,melee:true,pierce:0};
    schoolShotHit(shot,t);
    const hpBefore=t.hp;
    hitBuildTarget(t,event.damage);
    if(t.hp<hpBefore) meleeImpact(t,event);
    if(state.mode!=='playing') return;
    if(t.alive && event.stun) t.stunTimer=Math.max(t.stunTimer||0,event.stun);
    if(t===state.boss || t.alive) shiftTarget(t,state.player.x,state.player.y,event.push);
    if(t.alive) waveNeutralHit(t,deltaX(t.x,state.player.x),deltaY(t.y,state.player.y));
    for(const school of ['water','thunder']) if(effectLevel(school+'-attack') || school==='water' && (effectLevel('water-skill')||effectLevel('fusion-puddle'))) {
      schoolEffect(school,t,t.x,t.y,event.damage,hits);
      if(state.mode!=='playing') return;
    }
    if(effectLevel('splash-water')) {
      const radius=UPGRADE_TUNING.splashBaseRadius+effectLevel('splash-water')*UPGRADE_TUNING.splashPerLevel;
      skillVisual('splash',t.x,t.y,{radius});
      for(const other of combatTargets()) if(other!==t && !hits.includes(other) && Math.hypot(deltaX(other.x,t.x),deltaY(other.y,t.y))<radius) {hitBuildTarget(other,event.damage*BUILD_TUNING.supportSplashDamage);if(state.mode!=='playing')return;}
    }
    triggerMakerEffects('hit',t.x,t.y);
    if(state.mode!=='playing') return;
  }
  if(event.step && state.mode==='playing') {state.player.x+=Math.cos(event.angle)*event.step;state.player.y+=Math.sin(event.angle)*event.step;clampToMap(state.player);updateCamera();}
  // 風刃變成一次近距離追斬；不額外發射遠程水球。
  if(effectLevel('wind-blade')) {
    const other=combatTargets().find(t=>!hits.includes(t) && Math.hypot(deltaX(t.x,state.player.x),deltaY(t.y,state.player.y))<=event.radius+t.r && hits.some(h=>Math.hypot(deltaX(t.x,h.x),deltaY(t.y,h.y))<=r.windBladeRange));
    if(other) {skillVisual('gust',state.player.x,state.player.y,{x2:other.x,y2:other.y,color:BUILD_TUNING.wind.color});hitBuildTarget(other,event.damage*r.windBladeDamage);}
  }
}

tick:
function tick(dt) {
  if(state.mode==='playing') {
    state.juiceClock=(state.juiceClock||0)+dt;
    state.hitShake=countdown(state.hitShake||0,dt);
    if(!GAME_DATA.hitJuice.enabled || !GAME_DATA.hitJuice.intensity) {state.hitStop=0;state.hitShake=0;}
    if(state.hitStop>0) {state.hitStop=countdown(state.hitStop,dt);return;}
    for(const t of combatTargets()) t.impactSquash=countdown(t.impactSquash||0,dt);
  }
  if (state.mode === "playing" && state.slowMotion > 0) {
    state.slowMotion = countdown(state.slowMotion, dt);
    dt *= UPGRADE_TUNING.perfectSlowScale;
  }
  if (state.mode === "transition") {
    state.stageTransition = countdown(state.stageTransition, dt);
    if (state.stageTransition <= 0) { state.mode = "playing"; state.keys.clear(); updateActionControls(); }
    return;
  }
  if (state.mode !== "playing") return;
  if (openEncounterReward()) return;
  updateSkillVisuals(dt);
  updateMakerEffects(dt);
  if (state.mode !== "playing") return;
  state.elapsed += dt; state.stageElapsed += dt;
  startBookShooting();
  state.bookNoticeTimer = Math.max(0, state.bookNoticeTimer - dt);
  enemyNotice.hidden = state.bookNoticeTimer <= 0;
  const healLevel = effectLevel("auto-heal");
  if (healLevel > 0) {
    state.healTimer += dt;
    const healInterval = UPGRADE_TUNING.autoHealSeconds * Math.pow(BUILD_TUNING.healIntervalMultiplier, healLevel - 1);
    while (state.healTimer >= healInterval) {
      state.healTimer -= healInterval;
      if (state.player.health < maxPlayerHealth()) {
        state.player.health = Math.min(maxPlayerHealth(), state.player.health + 1);
        addHealEffect();
        updateHud();
      }
    }
  }
  const input = movementInput();
  let dx = input.x, dy = input.y;
  if (Math.hypot(dx, dy) > 0.01) {
    const length = Math.hypot(dx, dy); state.faceX = dx / length; state.faceY = dy / length;
  }
  const dashTime = Math.min(dt, state.dashTimer);
  const speed = PLAYER_SPEED * (1 + effectLevel("wind-light") * GAME_DATA.schoolRules.lightSpeed) * (1 + effectLevel("onion-dash") * UPGRADE_TUNING.moveSpeedPerLevel) * (outsideBossZone() ? 0.8 : 1) * syrupSpeed();
  const oldX = state.player.x, oldY = state.player.y;
  state.player.x += speed * (dx * (dt - dashTime) + state.dashX * gameSettings.dashMultiplier * dashTime);
  state.player.y += speed * (dy * (dt - dashTime) + state.dashY * gameSettings.dashMultiplier * dashTime);
  clampToMap(state.player); updateCamera();
  // 這幀有衝刺就保護到碰撞判斷結束，最後才扣時間。
  if (state.dashTimer > 0 && !state.player.damageDisabled) state.player.invincible = Math.max(state.player.invincible, dt);
  state.dashTimer = countdown(state.dashTimer, dt);
  if (dashTime > 0 && state.dashTimer === 0) schoolDashEnded();
  if (state.dashCharges < maxDashCharges()) {
    state.dashCooldown = countdown(state.dashCooldown, dt);
    if (state.dashCooldown <= 0) {
      state.dashCharges++;
      if (state.dashCharges < maxDashCharges()) state.dashCooldown = gameSettings.dashCooldown;
    }
  }
  if (dashTime > 0) state.dashAttack = UPGRADE_TUNING.dashAttackSeconds;
  else state.dashAttack = countdown(state.dashAttack, dt);
  state.dashGhosts = state.dashGhosts.filter(g => (g.life -= dt) > 0);
  if (dashTime > 0) state.dashGhosts.push({x:oldX,y:oldY,life:.22});
  state.skillCooldown = countdown(state.skillCooldown, dt);
  if (typeof tickManualAttack === "function") tickManualAttack(dt);
  if (state.mode !== "playing") return;
  updateActionControls();
  if (dashTime > 0) schoolDashCrossed(oldX,oldY,state.player.x,state.player.y);
  if (dashTime > 0) leaveDashTrail(state.player.x, state.player.y, Math.hypot(deltaX(state.player.x, oldX), deltaY(state.player.y, oldY)), oldX, oldY);
  state.moveRate = Math.hypot(deltaX(state.player.x, oldX), deltaY(state.player.y, oldY)) / Math.max(.001, dt) / PLAYER_SPEED;
  updateNeutralItems(dt);
  if (state.mode !== "playing") return;
  updateSchoolCombat(dt);
  if (state.mode !== "playing") return;
  updateUltimate(dt);
  if (state.mode !== "playing") return;
  updateFields(dt);
  if (state.mode !== "playing") return;
  updateBomb(dt);
  if (state.mode !== "playing") return;

  const moved = Math.hypot(deltaX(state.player.x, oldX), deltaY(state.player.y, oldY));
  state.player.moving = moved > 0.001;
  if (GAME_DATA.attackMode !== "manual") state.weaponAttack=SurvivorEffectBlocks.attackTick(state.weaponAttack,activeWeapon(),dt,state.player.moving);
  if (state.player.moving) state.player.walkPhase += moved / 12;
  else state.player.walkPhase = 0;
  if (deltaX(state.player.x, oldX)) state.player.facing = deltaX(state.player.x, oldX) > 0 ? 1 : -1;

  updatePacing(dt);
  updateEncounters(dt);
  state.spawnTimer -= dt;
  if (!state.boss && state.stageElapsed >= gameSettings.waveSeconds && state.bossIntro <= 0) summonTeacher();
  if (!state.boss) {
    let wave = currentWaves()[0];
    for (const row of currentWaves()) if (state.stageElapsed >= row.start) wave = row;
    const spawnEvery = wave.every / gameSettings.spawnScale / SurvivorPacing.density(GAME_DATA.pacing,state.stageElapsed);
    while (state.spawnTimer <= 0) { spawnEnemy(); state.spawnTimer += spawnEvery; }
  }
  if (state.bossIntro > 0) {
    state.bossIntro -= dt;
    for (const enemy of state.enemies) { if (enemy.miniboss) continue; enemy.x += (deltaX(state.boss.x, enemy.x)) * Math.min(1, dt * 3); enemy.y += (deltaY(state.boss.y, enemy.y)) * Math.min(1, dt * 3); }
    if (state.bossIntro <= 0) { burst(state.boss.x, state.boss.y, "#fff36b", 32); updateHud(); }
  }
  state.shotTimer -= dt;
  if (GAME_DATA.attackMode !== 'manual' && dashTime>0 && state.dashTimer===0 && activeWeapon().id==='candy-sword' && activeWeapon().dashThrust) {swingAtNearest(true);if(state.mode!=='playing')return;state.shotTimer=effectiveShotInterval()+state.attackRecovery;state.attackRecovery=0;}
  if (GAME_DATA.attackMode !== "manual" && state.shotTimer <= 0) { fireAtNearest(); if (state.mode !== "playing") return; state.shotTimer += effectiveShotInterval()+(state.attackRecovery||0); state.attackRecovery=0; }
  for (const enemy of state.enemies) {
    if (!enemy.alive) continue;
    const vx = deltaX(state.player.x, enemy.x), vy = deltaY(state.player.y, enemy.y);
    const distance = Math.max(0.01, Math.hypot(vx, vy));
    if(!targetVisible(enemy)) enemy.phaseAttack=null;
    updateEnemyBehavior(enemy,dt);
    if(state.mode!=="playing") return;
    if(!enemy.alive) continue;
    const direction=enemyDirection(enemy,distance), curve=enemy.behavior==='fast' ? Math.sin(enemy.wobble)*.65 : 0;
    const speed=enemy.speed*eliteSpeed(enemy)*direction*(enemy.stunTimer>0?0:1)*(enemy.slowTimer>0?(enemy.makerSlow||BUILD_TUNING.slowMultiplier):1)*(1+Math.floor(state.stageElapsed/30)*UPGRADE_TUNING.enemySpeedGrowth);
    enemy.x += (vx-vy*curve)/distance * speed * dt;
    enemy.y += (vy+vx*curve)/distance * speed * dt;
    if (enemy.knockback > 0) { const k = canAttackTarget(enemy) ? targetDisplacement(enemy,Math.min(enemy.knockback, KNOCKBACK_SPEED) * dt) : 0; enemy.x += enemy.knockX / distance * k; enemy.y += enemy.knockY / distance * k; enemy.knockback = Math.max(0, enemy.knockback - KNOCKBACK_SPEED * dt); }
    clampToMap(enemy);
    enemy.stunTimer = countdown(enemy.stunTimer || 0, dt);
    enemy.slowTimer = Math.max(0, (enemy.slowTimer || 0) - dt);
    enemy.wobble += dt * 6;
    enemy.flash = Math.max(0, enemy.flash - dt);
  }
  if(!GAME_DATA.bodySeparation.enabled) separateTanks();
  for (const shot of state.projectiles) {
    if (!shot.alive) continue;
    shot.x += shot.vx * dt; shot.y += shot.vy * dt;
    shot.rangeLeft -= Math.hypot(shot.vx, shot.vy) * dt;
    if (shot.rangeLeft <= 0) { if(shot.bigBubble) resolveWaterHit(shot); if(state.mode!=="playing")return; shot.alive = false; continue; }
    clampToMap(shot);
    for (const enemy of state.enemies) {
      if (enemy.alive && canAttackTarget(enemy) && !shot.hitList.includes(enemy) && Math.hypot(deltaX(enemy.x, shot.x), deltaY(enemy.y, shot.y)) < enemy.r + shot.r) {
        shot.hitList.push(enemy);
        schoolShotHit(shot, enemy);
        damageEnemy(enemy, shot.damage);
        if (!enemy.alive) splitNeutralShot(shot);
        for (const school of shot.schools || []) schoolEffect(school, enemy, school === "wind" ? state.player.x : enemy.x, school === "wind" ? state.player.y : enemy.y, shot.damage, shot.hitList);
        if (state.mode !== "playing") return;
        if (effectLevel("splash-water") > 0) {
          const radius = UPGRADE_TUNING.splashBaseRadius + effectLevel("splash-water") * UPGRADE_TUNING.splashPerLevel;
          skillVisual("splash", enemy.x, enemy.y, { radius });
          for (const nearby of state.enemies) if (nearby !== enemy && nearby.alive && canAttackTarget(nearby) && !shot.hitList.includes(nearby) && Math.hypot(deltaX(nearby.x, enemy.x), deltaY(nearby.y, enemy.y)) < radius) { shot.hitList.push(nearby); damageEnemy(nearby, shot.damage * BUILD_TUNING.supportSplashDamage); }
        }
        resolveWaterHit(shot);
        if (state.mode !== "playing") return;
        if (!shot.alive) break;
      }
    }
    if (shot.alive && state.boss && canAttackTarget(state.boss) && !shot.hitList.includes(state.boss) && Math.hypot(deltaX(state.boss.x, shot.x), deltaY(state.boss.y, shot.y)) < state.boss.r + shot.r) {
      shot.hitList.push(state.boss);
      const boss = state.boss;
      playSound("hit");
      schoolShotHit(shot, boss);
      boss.hp -= schoolDamage(boss, shot.damage); boss.flash = HIT_FLASH_SECONDS; boss.meleeFlash=false; updateHud();
      for (const school of shot.schools || []) schoolEffect(school, boss, school === "wind" ? state.player.x : boss.x, school === "wind" ? state.player.y : boss.y, shot.damage, shot.hitList);
      resolveWaterHit(shot);
      if (state.mode !== "playing") return;
      if (state.boss && state.boss.hp <= 0) { state.boss = null; finishRun(true); return; }
    }
  }
  for (let i = state.projectiles.length - 1; i >= 0; i--) {
    if (!state.projectiles[i].alive) state.projectilePool.push(state.projectiles.splice(i, 1)[0]);
  }
  state.enemies = state.enemies.filter((enemy) => enemy.alive);
  updateBookShooting(dt);
  updateBoss(dt);
  updateBossZone(dt);
  if (state.mode !== "playing") return;
  for (let i = state.enemyShots.length - 1; i >= 0; i--) {
    const shot = state.enemyShots[i];
    if(shot.phaseShot && (shot.life=countdown(shot.life,dt))<=0) {state.enemyShotPool.push(state.enemyShots.splice(i,1)[0]);continue;}
    shot.x += shot.vx * dt; shot.y += shot.vy * dt; clampToMap(shot);
    if (shot.source === "teacher" && (!state.boss || !targetVisible(state.boss) || !targetVisible(shot) || (shot.life -= dt) <= 0)) {
      state.enemyShotPool.push(state.enemyShots.splice(i, 1)[0]); continue;
    }
    if (schoolWindWall() && Math.hypot(deltaX(shot.x, state.player.x), deltaY(shot.y, state.player.y)) < GAME_DATA.schoolRules.eyeRadius + shot.r) { state.enemyShotPool.push(state.enemyShots.splice(i, 1)[0]); continue; }
    if (Math.hypot(deltaX(shot.x, state.player.x), deltaY(shot.y, state.player.y)) < state.player.r + shot.r) {
      if (state.practiceHit) pacingHurtPlayer(shot.damage || 0);
      if (!state.player.damageDisabled && state.player.invincible <= 0) { state.player.health = Math.max(0, state.player.health - absorbSchoolHit(shot.damage === undefined ? UPGRADE_TUNING.teacherShotDamage : shot.damage)); counterDischarge(); if (state.mode !== "playing") return; state.player.hitFlash = 0.16; state.player.invincible = INVINCIBLE_SECONDS; if (gameSettings.vibration && navigator.vibrate) navigator.vibrate(35); playSound("hurt"); updateHud(); }
      state.enemyShotPool.push(state.enemyShots.splice(i, 1)[0]);
    } else if (!shot.phaseShot && shot.source !== "teacher" && ((shot.life = (shot.life === undefined ? 8 : shot.life) - dt) <= 0)) state.enemyShotPool.push(state.enemyShots.splice(i, 1)[0]);
  }
  if (state.player.health <= 0) { finishRun(false); return; }
  for (const gem of state.gems) {
    if (!gem.alive) continue;
    gem.wobble += dt * 5;
    const dx = deltaX(state.player.x, gem.x), dy = deltaY(state.player.y, gem.y), distance = Math.hypot(dx, dy);
    const pullRadius = GEM_PULL_RADIUS * (effectLevel("item-magnet") ? GAME_DATA.neutralRules.magnetMultiplier : 1) * (1 + effectLevel("wind-light") * GAME_DATA.schoolRules.lightMagnet) * (1 + effectLevel("gem-magnet") * UPGRADE_TUNING.magnetPerLevel);
    if (distance < pullRadius && distance > 0.1) { const speed = 150 + (pullRadius - distance) * 3; gem.x += dx / distance * speed * dt; gem.y += dy / distance * speed * dt; }
    clampToMap(gem);
    if (distance < state.player.r + gem.r + 3) { gem.alive = false; neutralEvent("pickup", gem.x, gem.y); grantExperience(gem.value); if (state.mode === "levelup") break; }
  }
  if (state.mode === "levelup") return;
  for (let i = state.gems.length - 1; i >= 0; i--) {
    if (!state.gems[i].alive) state.gemPool.push(state.gems.splice(i, 1)[0]);
  }

  for (const effect of state.effects) { effect.life -= dt; effect.x += effect.vx * dt; effect.y += effect.vy * dt; clampToMap(effect); }
  for (let i = state.effects.length - 1; i >= 0; i--) {
    if (state.effects[i].life <= 0) state.effectPool.push(state.effects.splice(i, 1)[0]);
  }
  // 先判斷碰撞，再減少無敵時間，避免最後一幀又被撞一次。
  if (!state.player.damageDisabled && state.player.invincible <= 0) {
    const touchingEnemy = state.enemies.find((enemy) => enemy.alive && (enemy.miniboss || !GAME_DATA.bodyContact.pushOnly) && Math.hypot(deltaX(enemy.x, state.player.x), deltaY(enemy.y, state.player.y)) < enemy.r + state.player.r - 2);
    const touchingBoss = state.boss && targetVisible(state.boss) && state.bossIntro <= 0 && state.bossPhasePause <= 0 && !state.bossMoves.some(move => bossKind(move) === "dash") && Math.hypot(deltaX(state.boss.x, state.player.x), deltaY(state.boss.y, state.player.y)) < state.boss.r + state.player.r - 2;
    if (touchingEnemy || touchingBoss) {
      state.player.health = Math.max(0, state.player.health - absorbSchoolHit(touchingEnemy ? bodyContactDamage(touchingEnemy) : UPGRADE_TUNING.enemyDamage));
      counterDischarge(); if (state.mode !== "playing") return;
      state.player.invincible = INVINCIBLE_SECONDS;
      state.player.hitFlash = 0.16;
      if (gameSettings.vibration && navigator.vibrate) navigator.vibrate(35);
      playSound("hurt");
      updateHud();
    }
  }
  const bodyPass = dashTime>0 || state.dashBodyPass>0;
  separateEnemyBodies(dt,{x:oldX,y:oldY},bodyPass);
  state.dashBodyPass = countdown(state.dashBodyPass,dt);
  // 保留舊作品「只推開」行為；新分離關閉時才使用，不阻擋衝刺。
  if(!GAME_DATA.bodySeparation.enabled && !bodyPass) pushEnemyBodies();
  state.player.invincible = Math.max(0, state.player.invincible - dt);
  state.player.hitFlash = Math.max(0, state.player.hitFlash - dt);
  if (state.player.health <= 0) { finishRun(false); return; }
  statusEl.textContent = `${Math.floor(state.elapsed)} 秒`;
}

drawNeutralItems:
function drawNeutralItems() {
  if (!state.neutral) return;
  const p=state.player;
  if (effectLevel('item-bird')) {const pos=neutralBirdPosition();SurvivorIcons.draw(ctx,'item-bird',pos.x-12,pos.y-12,24);}
  for(const bomb of state.neutral.bombs) SurvivorIcons.draw(ctx,'item-candy',bomb.x-12,bomb.y-12,24+Math.sin(bomb.timer*20)*2);
  if (effectLevel('item-magnet')) {
    const radius=GEM_PULL_RADIUS*GAME_DATA.neutralRules.magnetMultiplier*(1+effectLevel('wind-light')*GAME_DATA.schoolRules.lightMagnet)*(1+effectLevel('gem-magnet')*UPGRADE_TUNING.magnetPerLevel);
    ctx.save();ctx.globalAlpha=.25;ctx.strokeStyle='#e5c77d';ctx.lineWidth=1;ctx.beginPath();ctx.arc(p.x,p.y,radius,0,Math.PI*2);ctx.stroke();ctx.restore();
  }
  ['crown','bank','clover','cookie'].filter(id=>effectLevel('item-'+id)).forEach((id,i)=>{
    SurvivorIcons.draw(ctx,'item-'+id,p.x-28+i*18,p.y-p.r-30,16);
    if(id==='bank'||id==='cookie') {ctx.fillStyle='#fff1b9';ctx.font='10px sans-serif';ctx.fillText(String(id==='bank'?Math.round(Math.min(GAME_DATA.neutralRules.bankCap,Math.floor(state.neutral.gems/GAME_DATA.neutralRules.bankEvery)*GAME_DATA.neutralRules.bankStep)*100)+'%':state.neutral.kills%GAME_DATA.neutralRules.cookieKills),p.x-28+i*18,p.y-p.r-32);}
  });
}

updateBomb:
function updateBomb(dt) {
  if (state.bombBlast) { state.bombBlast.life -= dt; if (state.bombBlast.life <= 0) state.bombBlast = null; }
  const bomb = state.bomb;
  if (!bomb) return;
  bomb.timer -= dt;
  if (bomb.timer > 0.000001) return;
  state.bomb = null; state.bombBlast = { x: bomb.x, y: bomb.y, radius: bomb.radius, life: 0.35, schools: bomb.schools };
  if (bomb.schools.includes("wind")) for (const target of combatTargets()) {
    if (Math.hypot(deltaX(target.x, bomb.x), deltaY(target.y, bomb.y)) <= bomb.radius * BUILD_TUNING.skillRadiusMultiplier + target.r) shiftTarget(target, bomb.x, bomb.y, -BUILD_TUNING.pullDistance);
  }
  if (bomb.schools.includes("water")) addField("water", bomb.x, bomb.y, bomb.radius);
  if (bomb.schools.includes("thunder")) {
    const block=cardBlock("thunder-skill","onSkillBlast",{radius:bomb.radius,damage:bomb.damage});
    skillVisual("discharge", bomb.x, bomb.y, { radius: bomb.radius, color: "#7737b0" });
    for (const target of combatTargets()) {
      if (cardBlockMatches(block.conditions[0],target,bomb.x,bomb.y)) { lightning(bomb.x, bomb.y, target.x, target.y); applyCardTargetActions(block,target); }
      if (state.mode !== "playing") return;
    }
  }
  function pushAway(target) {
    shiftTarget(target,bomb.x,bomb.y,bomb.knockback,true);
  }
  for (const enemy of state.enemies) {
    if (!enemy.alive || !canAttackTarget(enemy) || Math.hypot(deltaX(enemy.x, bomb.x), deltaY(enemy.y, bomb.y)) > bomb.radius + enemy.r) continue;
    damageEnemy(enemy, bomb.damage);
    if (enemy.alive) { pushAway(enemy); enemy.knockback = 0; }
  }
  if (state.boss && canAttackTarget(state.boss) && Math.hypot(deltaX(state.boss.x, bomb.x), deltaY(state.boss.y, bomb.y)) <= bomb.radius + state.boss.r) {
    state.boss.hp -= schoolDamage(state.boss, bomb.damage); state.boss.flash = HIT_FLASH_SECONDS; state.boss.meleeFlash=false; pushAway(state.boss); updateHud();
    if (state.boss.hp <= 0) { state.boss = null; finishRun(true); }
  }
  burst(bomb.x, bomb.y, "#80eaff", 20); playSound("explosion");
}
